const raw = $input.first().json;

// Parser le body correctement — supporte string avec = parasite
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

if (!data.task_id) {
  return [{
    json: {
      valid: "NO",
      error_code: "VALIDATION_ERROR",
      error_message: "task_id manquant",
      task_id: "unknown",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!data.results || typeof data.results !== 'object') {
  return [{
    json: {
      valid: "NO",
      error_code: "VALIDATION_ERROR",
      error_message: "Champ results manquant ou invalide",
      task_id: data.task_id,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    valid: "YES",
    task_id: data.task_id,
    results: {
      code_review: data.results.code_review || { status: "SKIP" },
      qa:          data.results.qa          || { status: "SKIP" },
      sast:        data.results.sast        || { status: "SKIP" },
      sca:         data.results.sca         || { status: "SKIP" },
      secrets:     data.results.secrets     || { status: "SKIP" },
      dast:        data.results.dast        || { status: "SKIP" }
    }
  }
}];

const input = $input.first().json;
const results = input.results || {};

// ── Extraction normalisée des résultats de chaque agent ──
function getStatus(r) { return String(r?.status || r?.Status || "SKIP").toUpperCase(); }
function getCritical(r) { return Array.isArray(r?.critical_issues) ? r.critical_issues.length : 0; }
function getScore(r) { return typeof r?.global_score === 'number' ? r.global_score : 100; }
function getCoverage(r) { return typeof r?.coverage === 'number' ? r.coverage : 100; }

const qa      = results.qa      || {};
const sast    = results.sast    || {};
const sca     = results.sca     || {};
const secrets = results.secrets || {};
const dast    = results.dast    || {};

// ── Règles STOP (bloquantes absolues) ──
const stopReasons = [];

if (getCritical(secrets) > 0)
  stopReasons.push(`Secrets exposés : ${getCritical(secrets)} secret(s) critique(s) détecté(s)`);

if (getCritical(sast) > 0)
  stopReasons.push(`SAST critique : ${getCritical(sast)} vulnérabilité(s) OWASP critique(s)`);

if (getCritical(dast) > 0)
  stopReasons.push(`DAST critique : ${getCritical(dast)} vulnérabilité(s) runtime critique(s)`);

if (getCritical(sca) > 0)
  stopReasons.push(`SCA critique : ${getCritical(sca)} CVE critique(s) dans les dépendances`);

// ── Règles REWORK (non bloquantes mais requièrent correction) ──
const reworkReasons = [];

if (getStatus(qa) === "FAIL")
  reworkReasons.push("QA : statut FAIL — problèmes qualité bloquants");

if (getStatus(qa) === "NEEDSIMPROVEMENT" && getCoverage(qa) < 50)
  reworkReasons.push(`QA : couverture insuffisante (${getCoverage(qa)}%)`);

if (getScore(sast) < 60)
  reworkReasons.push(`SAST : score insuffisant (${getScore(sast)}/100)`);

if (getScore(sca) < 60)
  reworkReasons.push(`SCA : score insuffisant (${getScore(sca)}/100)`);

if (getStatus(dast) === "NEEDSIMPROVEMENT")
  reworkReasons.push("DAST : avertissements de sécurité à corriger");

// ── Décision finale ──
let decision;
let blockingReasons = [];

if (stopReasons.length > 0) {
  decision = "STOP";
  blockingReasons = stopReasons;
} else if (reworkReasons.length > 0) {
  decision = "REWORK";
  blockingReasons = reworkReasons;
} else {
  decision = "CONTINUE";
}

// ── Score de risque global ──
const allScores = [
  getScore(qa),
  getScore(sast),
  getScore(sca),
  getScore(secrets),
  getScore(dast)
].filter(s => s !== 100 || true);

const riskScore = Math.round(
  100 - (allScores.reduce((a, b) => a + b, 0) / allScores.length)
);

// ── Rework target ──
let reworkTarget = null;
if (decision === "REWORK") {
  if (getStatus(sast) === "FAIL" || getCritical(sast) > 0) reworkTarget = "BACKEND";
  else if (getStatus(qa) === "FAIL") reworkTarget = "BACKEND";
  else reworkTarget = "BACKEND";
}

return [{
  json: {
    agent: "Agent Go/No-Go", _version: '1.1',
    task_id: input.task_id,
    decision,
    confidence: stopReasons.length > 0 ? 1.0 : reworkReasons.length > 0 ? 0.9 : 0.95,
    risk_score: riskScore,
    blocking_reasons: blockingReasons,
    warnings: reworkReasons,
    recommendations: decision === "CONTINUE"
      ? ["Pipeline validé — déploiement autorisé"]
      : decision === "REWORK"
        ? ["Corriger les points signalés et relancer le pipeline"]
        : ["Arrêt immédiat — corriger les vulnérabilités critiques avant toute relance"],
    rework_target: reworkTarget,
    approved_for_pipeline: decision === "CONTINUE",
    summary: `Décision : ${decision} — ${blockingReasons.length} raison(s) bloquante(s)`,
    results_summary: {
      qa:      { status: getStatus(qa),      score: getScore(qa) },
      sast:    { status: getStatus(sast),     score: getScore(sast) },
      sca:     { status: getStatus(sca),      score: getScore(sca) },
      secrets: { status: getStatus(secrets),  score: getScore(secrets) },
      dast:    { status: getStatus(dast),     score: getScore(dast) }
    },
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent Go/No-Go", _version: '1.1',
    task_id: input.task_id || "unknown",
    status: "ERROR",
    error_code: input.error_code || "VALIDATION_ERROR",
    error_message: input.error_message || "Erreur de validation",
    approved_for_pipeline: false,
    timestamp: input.timestamp || new Date().toISOString()
  }
}];
